    seen=set(); q=deque()
    for i in range(hh):
        for j in (0,ww-1):
            if g[i][j]==bg: seen.add((i,j)); q.append((i,j))
    for j in range(ww):
        for i in (0,hh-1):
            if g[i][j]==bg: seen.add((i,j)); q.append((i,j))
    while q:
        a,b=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
